int predict_fault(float V_rms, float I_rms, float A_55, float A_65, float A_50, float A_70, float I_neg, float THD, float A_fund) {
    double input[9] = {V_rms, I_rms, A_55, A_65, A_50, A_70, I_neg, THD, A_fund};
    double output[4] = {0.0, 0.0, 0.0, 0.0};
    score(input, output);
    int max_idx = 0;
    for (int i = 1; i < 4; i++) { if (output[i] > output[max_idx]) max_idx = i; }
    return max_idx;
}
